package com.diriktv.sidekick.player

import android.view.View
import android.view.accessibility.CaptioningManager
import android.widget.TextView
import androidx.media3.common.Player
import androidx.media3.common.text.CueGroup
import com.diriktv.sidekick.ui.AppFonts
import com.diriktv.sidekick.ui.dp
import com.diriktv.sidekick.ui.font

/**
 * Captions, drawn by Sidekick instead of the player's default subtitles.
 *
 * Kick's live captions (generated by its video service) arrive as a phrase that grows word by
 * word; each phrase ends a moment before the next begins, and the next starts by repeating the
 * last word or two. Shown as they come, the line blinks out between phrases and comes back with
 * old words. Here the phrases are joined into one running transcript, with the repeats dropped,
 * and its last two lines stay up through short pauses, fading only after a few seconds of quiet.
 */
internal class Captions(private val act: PlayerActivity, private val view: TextView) : Player.Listener {
    /** Words shown in the running transcript. */
    private val words = ArrayList<String>()
    /** The phrase being received (it grows in place), so its growth can be told from a new phrase. */
    private var phrase: List<String> = emptyList()
    /** Where in [words] the current phrase starts. */
    private var phraseStart = 0
    private val fade = Runnable { fadeOut() }

    init {
        val scale = (act.getSystemService(android.content.Context.CAPTIONING_SERVICE) as? CaptioningManager)?.fontScale ?: 1f
        view.textSize = 22f * scale
        view.font(AppFonts.Weight.MEDIUM)
        view.maxLines = 2
        view.setLineSpacing(act.dp(2).toFloat(), 1f)
    }

    override fun onCues(cueGroup: CueGroup) {
        val text = cueGroup.cues.joinToString(" ") { it.text?.toString().orEmpty() }.trim()
        if (text.isEmpty()) {
            // A pause between phrases: keep the line up a little in case more is coming.
            act.ui.removeCallbacks(fade)
            act.ui.postDelayed(fade, HOLD_MS)
            return
        }
        act.ui.removeCallbacks(fade)
        add(text.split(Regex("\\s+")))
        show()
        // A phrase that just stops (no empty cue after it) still fades in time.
        act.ui.postDelayed(fade, HOLD_MS + 4_000)
    }

    private fun add(incoming: List<String>) {
        val growing = phrase.isNotEmpty() && incoming.size >= phrase.size &&
            incoming.subList(0, phrase.size).map(::norm) == phrase.map(::norm)
        if (growing) {
            // The same phrase with more words: replace it in place.
            while (words.size > phraseStart) words.removeAt(words.size - 1)
            words.addAll(incoming)
        } else {
            // A new phrase: skip the words it repeats from the end of what's already shown.
            val overlap = overlap(incoming)
            phraseStart = words.size - overlap
            words.addAll(incoming.drop(overlap))
        }
        phrase = incoming
        // Only the last few lines' worth matters.
        if (words.size > MAX_WORDS) {
            val cut = words.size - MAX_WORDS
            repeat(cut) { words.removeAt(0) }
            phraseStart = (phraseStart - cut).coerceAtLeast(0)
        }
    }

    /** How many of [incoming]'s first words repeat the last words shown (up to a handful). */
    private fun overlap(incoming: List<String>): Int {
        for (k in minOf(MAX_OVERLAP, incoming.size, words.size) downTo 1) {
            val tail = words.subList(words.size - k, words.size).map(::norm)
            if (tail == incoming.subList(0, k).map(::norm)) return k
        }
        return 0
    }

    private fun norm(w: String) = w.lowercase().trim { !it.isLetterOrDigit() }

    private fun show() {
        view.text = fitted()
        if (view.visibility != View.VISIBLE || view.alpha < 1f) {
            view.animate().cancel()
            view.visibility = View.VISIBLE
            view.animate().alpha(1f).setDuration(150).start()
        }
    }

    /** The newest words that fit in two lines (older ones scroll off the top, as on TV). */
    private fun fitted(): String {
        val stage = (view.parent as? View)?.width ?: 0
        val room = minOf(view.maxWidth, stage - act.dp(96)) - view.paddingLeft - view.paddingRight
        if (room <= 0) return words.takeLast(12).joinToString(" ")
        var from = words.size
        while (from > 0) {
            val text = words.subList(from - 1, words.size).joinToString(" ")
            val lines = android.text.StaticLayout.Builder.obtain(text, 0, text.length, view.paint, room).build().lineCount
            if (lines > 2) break
            from--
        }
        return words.subList(from, words.size).joinToString(" ")
    }

    private fun fadeOut() {
        view.animate().alpha(0f).setDuration(300).withEndAction {
            view.visibility = View.INVISIBLE
            // Start the next line fresh, but remember the last words so a repeat isn't shown again.
            val keep = words.takeLast(MAX_OVERLAP)
            words.clear()
            words.addAll(keep)
            phraseStart = words.size
            view.text = ""
        }.start()
        phrase = emptyList()
    }

    /** Captions turned off, a seek, or a different stream: clear everything. */
    fun reset() {
        act.ui.removeCallbacks(fade)
        words.clear()
        phrase = emptyList()
        phraseStart = 0
        view.animate().cancel()
        view.text = ""
        view.visibility = View.INVISIBLE
    }

    override fun onPositionDiscontinuity(oldPosition: Player.PositionInfo, newPosition: Player.PositionInfo, reason: Int) {
        if (reason == Player.DISCONTINUITY_REASON_SEEK) reset()
    }

    /** The controls came up (or went): sit above them rather than under them. */
    fun lift(up: Boolean, by: Float) {
        view.animate().translationY(if (up) -by else 0f).setDuration(200).start()
    }

    private companion object {
        const val HOLD_MS = 3_000L
        const val MAX_WORDS = 40
        const val MAX_OVERLAP = 6
    }
}
